#include <iostream>
#include <utility>

void sort3(int &a, int &b, int &c) {
    if (a > b) {
        std::swap(a, b);
    }
    if (b > c) {
        std::swap(b, c);
    }
    if (a > b) {
        std::swap(a, b);
    }
}

int main() {
    int a, b, c;
    while (std::cin >> a >> b >> c) {
        sort3(a, b, c);
        std::cout << a << ' ' << b << ' ' << c << '\n';
    }
    return 0;
}

