#include <iostream>
#include <string>

bool is_digit(char c) {
    return c >= '0' && c <= '9';
}

bool parse_time(const std::string &text, int &hours, int &minutes) {
    if (text.size() != 5 || text[2] != ':' || !is_digit(text[0]) || !is_digit(text[1]) ||
        !is_digit(text[3]) || !is_digit(text[4])) {
        return false;
    }
    int h = (text[0] - '0') * 10 + (text[1] - '0');
    int m = (text[3] - '0') * 10 + (text[4] - '0');
    if (h > 23 || m > 59) {
        return false;
    }
    hours = h;
    minutes = m;
    return true;
}

int main() {
    std::string line;
    while (std::cin >> line) {
        int h, m;
        if (parse_time(line, h, m)) {
            std::cout << h * 60 + m << '\n';
        } else {
            std::cout << "ошибка\n";
        }
    }
    return 0;
}

