additionalExercises.referenceSolution:
#include <iostream>
#include <string>
#include <vector>

long long &cell(std::vector<long long> &grid, int cols, int r, int c) {
    return grid[static_cast<std::size_t>(r * cols + c)];
}

int main() {
    int rows, cols;
    if (!(std::cin >> rows >> cols)) {
        return 0;
    }
    std::vector<long long> grid(static_cast<std::size_t>(rows * cols), 0);
    std::string command;
    while (std::cin >> command) {
        int r = 0, c = 0;
        long long v = 0;
        std::cin >> r;
        if (command != "row") {
            std::cin >> c;
        }
        if (command == "set" || command == "add") {
            std::cin >> v;
        }
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            std::cout << "ошибка\n";
            continue;
        }
        if (command == "set") {
            cell(grid, cols, r, c) = v;
        } else if (command == "add") {
            cell(grid, cols, r, c) += v;
        } else if (command == "get") {
            std::cout << cell(grid, cols, r, c) << '\n';
        } else if (command == "row") {
            for (int j = 0; j < cols; j++) {
                std::cout << cell(grid, cols, r, j) << (j + 1 < cols ? ' ' : '\n');
            }
        }
    }
    return 0;
}

